async function buscarDados(url: string) {
  try {
    const res = await fetch(url);
    if (!res.ok) {
      throw new Error(`Erro HTTP: ${res.status}`);
    }
    return await res.json();
  } catch (err) {
    console.error(err);
  } finally {
    console.log("Requisição encerrada");
  }
}

